public class PaymentProcessor {
    private final PaymentGateway gateway;
    private final int maxAttempts;
    private final List<PaymentObserver> observers = new ArrayList<>();

    public PaymentProcessor(PaymentGateway gateway, int maxAttempts) {
        this.gateway = gateway;
        this.maxAttempts = maxAttempts;
    }

    public void addObserver(PaymentObserver observer) { observers.add(observer); }

    public ChargeResult charge(Order order) {
        int attempt = 1;
        long startedAt = System.currentTimeMillis();
        while (true) {
            try {
                ChargeResult result = gateway.charge(order.getAmount(), order.getCard());
                long duration = System.currentTimeMillis() - startedAt;
                PaymentEvent event = new PaymentEvent(order.getId(), order.getAmount(), duration, attempt);
                for (PaymentObserver observer : observers) observer.onSuccess(event);
                return result;
            } catch (RetryableException err) {
                if (attempt < maxAttempts) {
                    PaymentEvent event = new PaymentEvent(order.getId(), attempt, attempt * 200L);
                    for (PaymentObserver observer : observers) observer.onRetry(event);
                    attempt++;
                    continue;
                }
                PaymentEvent event = new PaymentEvent(order.getId(), err, attempt);
                for (PaymentObserver observer : observers) observer.onFailure(event);
                throw err;
            }
        }
    }
}

