class RecordingObserver : public PaymentObserver {
public:
    std::vector<PaymentEvent> successEvents;
    std::vector<PaymentEvent> failureEvents;

    void onSuccess(const PaymentEvent& event) override { successEvents.push_back(event); }
    void onFailure(const PaymentEvent& event) override { failureEvents.push_back(event); }
};

TEST(PaymentProcessorTest, ChargeFiresOnSuccessWithCorrectOrderId) {
    auto recorder = std::make_shared<RecordingObserver>();
    PaymentProcessor processor(fakeGateway, 3);
    processor.addObserver(recorder);

    processor.charge(Order("order-1", 500, fakeCard));

    EXPECT_EQ("order-1", recorder->successEvents.at(0).orderId());
}

