def notify(self, hook_name, event):
    for observer in self.observers:
        try:
            hook = getattr(observer, hook_name, None)
            if callable(hook):
                hook(event)
        except Exception as observer_error:
            # an observer failing must never break the operation it is watching
            self.internal_logger.warning(
                "observer failed", extra={"hook": hook_name, "error": observer_error}
            )

