void notify(const std::string& hookName, const PaymentEvent& event) {
    for (const auto& observer : observers) {
        try {
            if (hookName == "onSuccess")      observer->onSuccess(event);
            else if (hookName == "onFailure") observer->onFailure(event);
            else if (hookName == "onRetry")   observer->onRetry(event);
        } catch (const std::exception& observerError) {
            // an observer failing must never break the operation it is watching
            internalLogger.warn("observer failed, hook=" + hookName + ", error=" + observerError.what());
        }
    }
}

